from pybricks.parameters import Stop
from pybricks.tools import wait

from Team_Phoenix_Library import (
    phoenix_gyro_spin_turn_the_old_way,
    phoenix_gyro_straight,
    phoenix_gyro_turn,
)

# Set up.
cefmfce = 0

def run_white_mission(drive_base, left_drive, right_drive2, left_attachment, right_attachment):
    global cefmfce
    drive_base.use_gyro(True)
    right_attachment.run_angle(50, 135)
    phoenix_gyro_straight(630, 300, 0, 1.5, drive_base, left_drive, right_drive2)
    left_attachment.run_angle(500, 400)
    phoenix_gyro_turn(100, 60, 30, 90, 'right', drive_base)
    wait(50)
    print(drive_base.angle())
    cefmfce = 90 - drive_base.angle()
    phoenix_gyro_straight(320, 300, cefmfce, 1, drive_base, left_drive, right_drive2)
    phoenix_gyro_spin_turn_the_old_way(125, -65, 45, -90.5, 'left', drive_base, left_drive, right_drive2)
    wait(50)
    print(drive_base.angle())
    cefmfce = -90 - drive_base.angle()
    phoenix_gyro_straight(50, 125, cefmfce, 1.5, drive_base, left_drive, right_drive2)
    right_attachment.run_angle(500, 1500)
    phoenix_gyro_straight(50, 125, cefmfce, 1.5, drive_base, left_drive, right_drive2)
    drive_base.straight(-50)
    right_attachment.run_angle(500, 1500)
    drive_base.use_gyro(True)
    drive_base.settings(turn_rate=90)
    right_attachment.run_angle(50, 85)
    drive_base.straight(-140)
    phoenix_gyro_spin_turn_the_old_way(125, -117, 45, -130, 'left', drive_base, left_drive, right_drive2)
    wait(30)
    print(drive_base.angle())
    left_attachment.run(-90)
    wait(1500)
    left_attachment.stop()
    drive_base.settings(straight_speed=600)
    drive_base.drive(650, -45)
    wait(1575)
    drive_base.stop()


